public class FileExtensionValidator { static String validateFileExtension(String name){int i=name.lastIndexOf('.');if(i<1||i==name.length()-1)return "Rejected - invalid file type";String e=name.substring(i+1);return e.equalsIgnoreCase("pdf")||e.equalsIgnoreCase("docx")||e.equalsIgnoreCase("zip")?"Accepted":"Rejected - invalid file type";} public static void main(String[] args){System.out.println(validateFileExtension("Assignment1.PDF"));} }
